{
  "findings": [
    {
      "check_id": "CKV2_AWS_41",
      "title": "EC2 instance has no IAM role attached",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance has no instance profile, preventing workloads from using a controlled AWS identity and potentially encouraging use of long-lived credentials."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance may receive a public IP address",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance is placed in a public subnet without explicitly disabling public IP assignment, which could expose it directly to the internet depending on the subnet configuration."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "EC2 instance does not require IMDSv2",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "No metadata options require session tokens, so the instance can use IMDSv1 and is more vulnerable to metadata credential theft through SSRF."
    }
  ],
  "patched_code": "resource "aws_iam_role" "levelup_instance" {
  name_prefix = "levelup-instance-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "levelup_instance" {
  name_prefix = "levelup-instance-"
  role        = aws_iam_role.levelup_instance.name
}

resource "aws_instance" "MyFirstInstnace" {
  ami                         = lookup(var.AMIS, var.AWS_REGION)
  instance_type               = "t2.micro"
  availability_zone           = "us-east-2a"
  key_name                    = aws_key_pair.levelup_key.key_name
  vpc_security_group_ids      = [aws_security_group.allow-levelup-ssh.id]
  subnet_id                   = aws_subnet.levelupvpc-public-1.id
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.levelup_instance.name

  metadata_options {
    http_tokens = "required"
  }
}
",
  "fix_summary": "Attached a least-privilege EC2 IAM role with no permissions, explicitly disabled public IP assignment, and required IMDSv2 session tokens."
}
